+  console.log(`\n${domain.id}`);
+  console.log(`  changed: ${matches.join(', ')}`);
+  console.log(`  update: ${domain.update.join(', ')}`);
+  console.log(`  gate: ${domain.gate}`);
+}
+if (!matched) console.log('No configured language impact domain matched these paths.');

