+  console.error(`FAIL missing required language-context source(s): ${missing.join(', ')}`);
+  process.exit(1);
+}
+const sourceSetDigest = sha(
+  Object.entries(records)
+    .sort(([a], [b]) => a.localeCompare(b))
+    .map(([id, record]) => `${id}:${record.sha256}`)
+    .join('\n'),
