+  const candidates = [
+    join(languageRoot, '02-canonical', name),
+    join(languageRoot, name),
+    join(PACKAGE_ROOT, '02-canonical', name),
+  ];
+  const path = candidates.find(existsSync);
+  if (!path) throw new Error(`Missing route-coverage artifact: ${name}`);
