+    const cells = [];
+    let value = '';
+    let quoted = false;
+    for (let index = 0; index < line.length; index += 1) {
+      const char = line[index];
+      if (char === '"') {
+        if (quoted && line[index + 1] === '"') {
+          value += '"';
+          index += 1;
+        } else {
+          quoted = !quoted;
+        }
+      } else if (char === ',' && !quoted) {
+        cells.push(value);
+        value = '';
+      } else {
+        value += char;
+      }
+    }
+    cells.push(value);
+    return cells;
+  };
+  const headers = split(lines[0]);
+  return lines
+    .slice(1)
+    .map((line) =>
+      Object.fromEntries(headers.map((header, index) => [header, split(line)[index] ?? ''])),
+    );
