+unique(
+  entries.map((entry) => entry.sourcePath),
+  'inventory source path',
+);
+unique(
+  entries.map((entry) => entry.route),
+  'inventory route',
+);
+unique(
+  entries.map((entry) => entry.pageId),
+  'inventory page id',
+);
