+    fail(`public route ${row.route} (${row.id}) has no inventory entry`);
+    continue;
+  }
+  if (entry.pageId !== row.id)
+    fail(`inventory ${entry.id} page ID ${entry.pageId} does not match route-map ID ${row.id}`);
